CREATE TABLE IF NOT EXISTS "app_users" ("ifc_user_id" text PRIMARY KEY NOT NULL,"ifc_username" text,"discord_user_id" text,"discord_username" text,"onboarding_completed_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "app_users_discord_user_id_uq" ON "app_users" ("discord_user_id");
CREATE TABLE IF NOT EXISTS "application_codes" ("id" text PRIMARY KEY NOT NULL,"code_hash" text NOT NULL UNIQUE,"issued_to_ifc_user_id" text,"created_by_ifc_user_id" text NOT NULL,"expires_at" timestamptz,"used_at" timestamptz,"used_by_ifc_user_id" text,"revoked_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "application_codes_status_idx" ON "application_codes" ("used_at","expires_at");
CREATE TABLE IF NOT EXISTS "crew_requests" ("id" text PRIMARY KEY NOT NULL,"schedule_id" text NOT NULL,"aircraft_id" text NOT NULL,"pilot_ifc_user_id" text NOT NULL,"seat" text NOT NULL,"status" text NOT NULL DEFAULT 'pending',"discord_message_id" text,"decided_by_ifc_user_id" text,"decided_at" timestamptz,"failure_code" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "crew_requests_schedule_idx" ON "crew_requests" ("schedule_id","status");
CREATE INDEX IF NOT EXISTS "crew_requests_pilot_idx" ON "crew_requests" ("pilot_ifc_user_id","status");
CREATE UNIQUE INDEX IF NOT EXISTS "crew_requests_active_seat_uq" ON "crew_requests" ("schedule_id","seat") WHERE "status" IN ('pending','processing','approved');
CREATE TABLE IF NOT EXISTS "active_crew_assignments" ("id" text PRIMARY KEY NOT NULL,"schedule_id" text NOT NULL,"aircraft_id" text NOT NULL,"pilot_ifc_user_id" text NOT NULL,"seat" text NOT NULL,"request_id" text,"status" text NOT NULL DEFAULT 'assigned',"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "active_crew_schedule_idx" ON "active_crew_assignments" ("schedule_id","status");
CREATE INDEX IF NOT EXISTS "active_crew_pilot_idx" ON "active_crew_assignments" ("pilot_ifc_user_id","status");
CREATE TABLE IF NOT EXISTS "discord_integrations" ("id" text PRIMARY KEY NOT NULL,"guild_id" text,"crew_requests_channel_id" text,"notifier_channel_id" text,"auto_crew_channel_id" text,"schedule_reviser_channel_id" text,"auto_crew_role_id" text,"waitlist_role_id" text,"updated_by_ifc_user_id" text,"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "feature_settings" ("feature_key" text PRIMARY KEY NOT NULL,"enabled" boolean NOT NULL DEFAULT false,"updated_by_ifc_user_id" text,"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "admin_operator_credentials" ("ifc_user_id" text PRIMARY KEY NOT NULL,"encrypted_session" text NOT NULL,"connected_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "automation_alerts" ("id" text PRIMARY KEY NOT NULL,"alert_key" text NOT NULL UNIQUE,"alert_type" text NOT NULL,"aircraft_id" text NOT NULL,"schedule_id" text NOT NULL,"status" text NOT NULL DEFAULT 'open',"discord_message_id" text,"claimed_by_ifc_user_id" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" text PRIMARY KEY NOT NULL,"actor_ifc_user_id" text NOT NULL,"action" text NOT NULL,"target_type" text NOT NULL,"target_id" text NOT NULL,"metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "audit_logs_created_idx" ON "audit_logs" ("created_at");
CREATE TABLE IF NOT EXISTS "notification_outbox" ("id" text PRIMARY KEY NOT NULL,"event_type" text NOT NULL,"entity_id" text NOT NULL UNIQUE,"status" text NOT NULL DEFAULT 'pending',"attempts" integer NOT NULL DEFAULT 0,"next_attempt_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
